messages.content:
Write a single self-contained HTML file with a 3D animation using three.js. three.js r160 is available as an ES module at './three.module.js' -- import it with:
  import * as THREE from './three.module.js';
Scene: a low-poly 3D humanoid figure performs this exact cycle on a treadmill-style ground, side-on camera: stands still for 2 seconds, walks in place for 3 seconds (limbs swinging at walking pace), runs in place for 3 seconds (faster, larger limb swings, slight forward lean), then stands still again for 2 seconds. The 10-second cycle loops forever and must start immediately on load. Limb movement must clearly differ between walking and running. No external assets besides the three.js import. Output ONLY the HTML in one code block.

response.text:
```html
<!DOCTYPE html>
<html lang="en">
<head>
    <meta charset="UTF-8">
    <meta name="viewport" content="width=device-width, initial-scale=1.0">
    <title>Low Poly Humanoid Treadmill Animation</title>
    <style>
        body { margin: 0; overflow: hidden; background-color: #1a1a1a; }
        canvas { display: block; }
    </style>
</head>
<body>
    <!-- Import map to ensure we use the local module -->
    <script type="importmap">
        {
            "imports": {
                "three": "./three.module.js"
            }
        }
    </script>

    <script type="module">
        import * as THREE from './three.module.js';

        // --- Configuration ---
        const CYCLE_STEPS = [
            { name: 'stand', duration: 2.0, factor: 0 },
            { name: 'walk',  duration: 3.0, factor: 0.5 }, // Walking speed
            { name: 'run',   duration: 3.0, factor: 1.0 }, // Running speed
            { name: 'stand', duration: 2.0, factor: 0 }
        ];
        const TOTAL_CYCLE_TIME = CYCLE_STEPS.reduce((acc, step) => acc + step.duration, 0);

        // --- Scene Setup ---
        const scene = new THREE.Scene();
        scene.background = new THREE.Color(0x222222);

        const camera = new THREE.PerspectiveCamera(45, window.innerWidth / window.innerHeight, 0.1, 100);
        // Side-on camera position
        camera.position.set(0, 2, 8);
        camera.lookAt(0, 1, 0);

        const renderer = new THREE.WebGLRenderer({ antialias: true });
        renderer.setSize(window.innerWidth, window.innerHeight);
        renderer.shadowMap.enabled = true;
        document.body.appendChild(renderer.domElement);

        // --- Lighting ---
        const ambientLight = new THREE.AmbientLight(0xffffff, 0.4);
        scene.add(ambientLight);

        const dirLight = new THREE.DirectionalLight(0xffffff, 0.8);
        dirLight.position.set(5, 10, 7);
        dirLight.castShadow = true;
        dirLight.shadow.mapSize.width = 1024;
        dirLight.shadow.mapSize.height = 1024;
        scene.add(dirLight);

        // --- Materials ---
        // Low poly aesthetic using flat shading
        const skinMaterial = new THREE.MeshToonMaterial({ color: 0xffccaa, flatShading: true });
        const clothMaterial = new THREE.MeshToonMaterial({ color: 0x3366cc, flatShading: true });
        const shoeMaterial = new THREE.MeshToonMaterial({ color: 0x111111, flatShading: true });
        const groundMaterial = new THREE.MeshToonMaterial({ color: 0x444444, flatShading: true });

        // --- The Treadmill / Ground ---
        const groundGeo = new THREE.BoxGeometry(8, 0.5, 4);
        const ground = new THREE.Mesh(groundGeo, groundMaterial);
        ground.position.y = -0.25;
        ground.receiveShadow = true;
        scene.add(ground);

        // --- The Character ---
        const characterGroup = new THREE.Group();
        characterGroup.position.y = 2; // Adjust so feet are on ground
        scene.add(characterGroup);

        // Helper to create low-poly parts
        function createPart(geometry, material, position) {
            const mesh = new THREE.Mesh(geometry, material);
            mesh.position.set(...position);
            mesh.castShadow = true;
            mesh.receiveShadow = true;
            return mesh;
        }

        // 1. Torso
        const torsoGeo = new THREE.ConeGeometry(0.4, 1.2, 4);
        const torso = createPart(torsoGeo, clothMaterial, [0, 0.6, 0]);
        // Rotate to face side (Z axis)
        torso.rotation.z = Math.PI / 2;
        characterGroup.add(torso);

        // 2. Head
        const headGeo = new THREE.SphereGeometry(0.25, 4, 4);
        const head = createPart(headGeo, skinMaterial, [0, 1.4, 0]);
        head.rotation.z = Math.PI / 2;
        characterGroup.add(head);

        // 3. Limbs (Geometry: Capsule or Cylinder)
        const limbGeo = new THREE.CylinderGeometry(0.08, 0.08, 0.6, 4);

        // Helper to create limb with pivot at one end
        function createLimb(type, xPos, zPos) {
            const limb = new THREE.Group();
            const mesh = new THREE.Mesh(limbGeo, skinMaterial);
            mesh.position.y = -0.3; // Offset so pivot is at top of cylinder
            mesh.castShadow = true;
            limb.add(mesh);

            // Position relative to torso center
            limb.position.set(xPos, 0.8, zPos);

            // Rotate to point sideways
            limb.rotation.z = Math.PI / 2;

            characterGroup.add(limb);
            return limb;
        }

        const leftArm = createLimb('arm', -0.3, 0.2);
        const rightArm = createLimb('arm', 0.3, -0.2);
        const leftLeg = createLimb('leg', -0.2, 0.3);
        const rightLeg = createLimb('leg', 0.2, -0.3);

        // --- Animation Logic ---

        let startTime = null;

        function animate(time) {
            requestAnimationFrame(animate);

            if (!startTime) startTime = time;
            const elapsed = (time - startTime) / 1000;

            // Calculate current step in cycle
            const cycleProgress = (elapsed % TOTAL_CYCLE_TIME) / TOTAL_CYCLE_TIME;

            let currentStepIndex = 0;
            let accumulatedTime = 0;
            let stepFactor = 0;
            let isRunning = false;
            let isWalking = false;

            // Find which step we are in
            for (let i = 0; i < CYCLE_STEPS.length; i++) {
                if (cycleProgress < accumulatedTime + CYCLE_STEPS[i].duration / TOTAL_CYCLE_TIME) {
                    currentStepIndex = i;
                    // Calculate progress within this specific step (0 to 1)
                    const stepProgress = (cycleProgress * TOTAL_CYCLE_TIME - accumulatedTime) / CYCLE_STEPS[i].duration;

                    // Map step progress to interpolation factor based on data
                    // Step data has 'factor' which represents the intensity of the motion relative to max
                    // However, for walking/running, we want a sine wave. 
                    // Let's define speed: factor 0 = speed 0, factor 1 = max speed.

                    // We need a time value that scales with speed
                    stepFactor = CYCLE_STEPS[i].factor;

                    if (CYCLE_STEPS[i].name === 'walk') isWalking = true;
                    if (CYCLE_STEPS[i].name === 'run') isRunning = true;

                    break;
                }
                accumulatedTime += CYCLE_STEPS[i].duration;
            }

            // Animation Physics
            // Base time for sine waves. If speed is 0, we don't want oscillation.
            const speed = stepFactor;
            const animationTime = elapsed * speed * 2; // Multiplier for frequency

            // 1. Limb Rotation (Sine waves with phase offsets)
            const swingRangeWalk = 1.0; // Radians
            const swingRangeRun = 1.5;  // Radians (larger swings)

            // Mixing: Linear interpolation between 0 and range based on speed
            const currentRange = isWalking ? swingRangeWalk : (isRunning ? swingRangeRun : 0);

            // Legs: Opposed
            const leftLegRot = Math.sin(animationTime) * currentRange;
            const rightLegRot = Math.sin(animationTime + Math.PI) * currentRange;

            // Arms: Opposed to legs (usually)
            const leftArmRot = Math.sin(animationTime + Math.PI) * currentRange;
            const rightArmRot = Math.sin(animationTime) * currentRange;

            // Apply Rotations (Local Z axis because we rotated the group Z=PI/2 to face side)
            leftLeg.rotation.z = leftLegRot;
            rightLeg.rotation.z = rightLegRot;
            leftArm.rotation.z = leftArmRot;
            rightArm.rotation.z = rightArmRot;

            // 2. Body Position / Lean

            // Squat/Bounce (Amplitude based on speed)
            const bounce = Math.abs(Math.sin(animationTime)) * (speed * 0.1);

            // Lean forward when running
            const lean = isRunning ? Math.sin(animationTime) * 0.1 : 0;

            // Apply to main character group
            characterGroup.position.y = bounce;
            characterGroup.rotation.z = lean; // Forward lean

            // 3. Treadmill Visuals (Moving floor texture or pattern)
            // Since it's just a box, we can rotate it to simulate movement
            if (speed > 0) {
                ground.rotation.y += speed * 0.05;
            } else {
                ground.rotation.y = 0;
            }

            renderer.render(scene, camera);
        }

        // Handle window resize
        window.addEventListener('resize', () => {
            camera.aspect = window.innerWidth / window.innerHeight;
            camera.updateProjectionMatrix();
            renderer.setSize(window.innerWidth, window.innerHeight);
        });

        // Start animation loop immediately
        requestAnimationFrame(animate);

    </script>
</body>
</html>
```
